<?php
function qcClauseCatalog(){
 foreach([dirname(__DIR__).'/nuevo/static/data/proforma-contract-clauses.json',dirname(__DIR__,2).'/static/data/proforma-contract-clauses.json'] as $path){if(is_file($path)){$data=json_decode(file_get_contents($path),true);if(is_array($data)&&count($data)>0)return $data;}}
 throw new RuntimeException('Contract clause catalog unavailable');
}
function qcContractReference($source){return str_pad((string)($source['quote']['Numero']??''),3,'0',STR_PAD_LEFT).'-'.($source['quote']['Anio']??'');}
function qcTemplateInput($body,$source){
 if(isset($body['incluirRubricaConsultor'])&&!is_bool($body['incluirRubricaConsultor']))throw new InvalidArgumentException('Revisa la opción de rúbrica.');
 $out=['cargoConsultor'=>'CONSULTOR DE TI','incluirRubricaConsultor'=>$body['incluirRubricaConsultor']??true];$defaults=['numeroContrato'=>qcContractReference($source),'ciudad'=>'','documentoConsultor'=>'','documentoRepresentanteCliente'=>'','documentoRepresentanteProveedor'=>'','soporteVigencia'=>'','cuentasPago'=>''];
 foreach(['numeroContrato'=>40,'ciudad'=>100,'documentoConsultor'=>20,'documentoRepresentanteCliente'=>20,'documentoRepresentanteProveedor'=>20,'soporteVigencia'=>1000,'cuentasPago'=>3000] as $key=>$max){$value=$body[$key]??$defaults[$key];if(!is_string($value)||mb_strlen($value)>$max||preg_match('/[\x00-\x08\x0b\x0c\x0e-\x1f]/',$value))throw new InvalidArgumentException('Revisa el campo '.$key.'.');$out[$key]=trim($value);}
 if(!preg_match('/^[A-Za-z0-9][A-Za-z0-9 .\/-]{0,39}$/D',$out['numeroContrato']))throw new InvalidArgumentException('Indica una referencia de contrato válida.');
 foreach(['documentoConsultor','documentoRepresentanteCliente','documentoRepresentanteProveedor'] as $key)if($out[$key]!==''&&(!preg_match('/^[A-Za-z0-9-]{6,20}$/D',$out[$key])||preg_match('/^0+$/D',$out[$key])))throw new InvalidArgumentException('Revisa el documento del firmante.');
 $ids=$body['compromisos']??[];if(!is_array($ids)||count($ids)>6||array_values($ids)!==$ids)throw new InvalidArgumentException('Selecciona los compromisos del contrato.');$catalog=array_column(qcClauseCatalog(),null,'id');$out['compromisos']=[];$out['compromisosDetalle']=[];
 foreach($ids as $id){if(!is_string($id)||!isset($catalog[$id]))throw new InvalidArgumentException('Compromiso de contrato no disponible.');if(!in_array($id,$out['compromisos'],true)){$out['compromisos'][]=$id;$out['compromisosDetalle'][]=$catalog[$id];}}
 $out['formatoCuentas']=qcPaymentMode($body);
 if($out['formatoCuentas']!=='imagen'&&$out['cuentasPago']==='')throw new InvalidArgumentException('Escribe las cuentas bancarias y los datos para el pago.');
 return $out;
}
function qcPaymentMode($form){
 $mode=$form['formatoCuentas']??(trim((string)($form['cuentasPago']??''))!==''?'texto':'imagen');
 if(!is_string($mode)||!in_array($mode,['imagen','texto','ambos'],true))throw new InvalidArgumentException('Selecciona cómo mostrar las cuentas bancarias.');
 return $mode;
}
function qcPaymentImage(){
 $path=dirname(__DIR__).'/resources/images/cuentas.png';if(!is_file($path))$path=dirname(__DIR__,2).'/resources/images/cuentas.png';
 if(!is_file($path)||filesize($path)>2000000)throw new RuntimeException('La imagen de cuentas de la proforma no está disponible.');
 $bytes=file_get_contents($path);$size=getimagesizefromstring($bytes);if(!$size||$size['mime']!=='image/png')throw new RuntimeException('Revisa la imagen de cuentas de la proforma.');
 return ['mime'=>'image/png','base64'=>base64_encode($bytes),'sha256'=>hash('sha256',$bytes)];
}
function qcPaymentAccountsHtml($data){
 $form=$data['form'];$mode=qcPaymentMode($form);$body='';
 if($mode!=='texto'){
  // New versions retain the exact company image. Earlier drafts use the proforma image.
  $image=array_key_exists('paymentAccountsImage',$data)?$data['paymentAccountsImage']:qcPaymentImage();
  $encoded=$image['base64']??null;$sha=$image['sha256']??null;
  $bytes=is_string($encoded)&&strlen($encoded)<=2666668?base64_decode($encoded,true):false;
  if(($image['mime']??'')!=='image/png'||$bytes===false||!is_string($sha)||!hash_equals(hash('sha256',$bytes),$sha))throw new RuntimeException('La copia de las cuentas bancarias no es válida.');
  $body.='<img class="bank-accounts-image" alt="Cuentas bancarias de la empresa, como en la proforma" src="data:image/png;base64,'.$encoded.'">';
 }
 if($mode!=='imagen'&&trim((string)($form['cuentasPago']??''))!=='')$body.='<div class="accounts">'.qpEscape($form['cuentasPago']).'</div>';
 return '<section class="bank-accounts"><h2>INFORMACIÓN DE PAGO · CUENTAS BANCARIAS</h2>'.$body.'</section>';
}
function qcNumberWords($n){
 $n=(int)$n;$small=['cero','uno','dos','tres','cuatro','cinco','seis','siete','ocho','nueve','diez','once','doce','trece','catorce','quince','dieciséis','diecisiete','dieciocho','diecinueve','veinte','veintiuno','veintidós','veintitrés','veinticuatro','veinticinco','veintiséis','veintisiete','veintiocho','veintinueve'];
 if($n<30)return $small[$n];if($n<100){$t=[3=>'treinta',4=>'cuarenta',5=>'cincuenta',6=>'sesenta',7=>'setenta',8=>'ochenta',9=>'noventa'];return $t[intdiv($n,10)].($n%10?' y '.$small[$n%10]:'');}
 if($n===100)return 'cien';if($n<1000){$h=[1=>'ciento',2=>'doscientos',3=>'trescientos',4=>'cuatrocientos',5=>'quinientos',6=>'seiscientos',7=>'setecientos',8=>'ochocientos',9=>'novecientos'];return $h[intdiv($n,100)].($n%100?' '.qcNumberWords($n%100):'');}
 $apocope=function($word){return preg_replace(['/veintiuno$/u','/ y uno$/u','/^uno$/u'],['veintiún',' y un','un'],$word);};
 if($n<1000000)return ($n<2000?'mil':$apocope(qcNumberWords(intdiv($n,1000))).' mil').($n%1000?' '.qcNumberWords($n%1000):'');
 return ($n<2000000?'un millón':$apocope(qcNumberWords(intdiv($n,1000000))).' millones').($n%1000000?' '.qcNumberWords($n%1000000):'');
}
function qcMoneyWords($cents){return mb_strtoupper(qcNumberWords(intdiv($cents,100)).' con '.str_pad((string)($cents%100),2,'0',STR_PAD_LEFT).'/100 soles','UTF-8');}
function qcFormalDate($date){$d=new DateTimeImmutable($date);$months=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];return $d->format('j').' de '.$months[(int)$d->format('n')-1].' de '.$d->format('Y');}
function qcPdfNumberPages($pdf){$font=$pdf->getFontMetrics()->getFont('DejaVu Sans','normal');$pdf->getCanvas()->page_text(502,818,'{PAGE_NUM} / {PAGE_COUNT}',$font,7,[0.54,0.42,0.47]);}
function qcTextParagraphs($text){$html='';foreach(preg_split('/\r?\n\s*\r?\n/',trim((string)$text)) as $p)if(trim($p)!=='')$html.='<p>'.nl2br(qpEscape(trim($p))).'</p>';return $html;}
